import os
import queue
from typing import Iterable, Iterator, Optional, Union, Any, Callable

import azure.cognitiveservices.speech as speechsdk


class StreamingSpeechToText:
    def __init__(
        self,
        language: str = "en-US",
        subscription_key: Optional[str] = None,
        region: Optional[str] = None,
        sample_rate_hz: int = 16000,
        audio_format: str = "pcm",
    ) -> None:
        self.subscription_key = subscription_key or os.getenv("AZURE_SPEECH_KEY")
        self.region = region or os.getenv("AZURE_SPEECH_REGION")
        if not self.subscription_key or not self.region:
            raise ValueError(
                "Azure Speech credentials are required: AZURE_SPEECH_KEY and AZURE_SPEECH_REGION"
            )

        self.language = language
        self.sample_rate_hz = sample_rate_hz
        self.audio_format = audio_format.lower()

        self._speech_config = speechsdk.SpeechConfig(
            subscription=self.subscription_key,
            region=self.region,
        )
        self._speech_config.speech_recognition_language = self.language

        if self.audio_format == "pcm":
            audio_format_obj = speechsdk.audio.AudioStreamFormat(
                samples_per_second=self.sample_rate_hz,
                bits_per_sample=16,
                channels=1,
            )
        else:
            raise ValueError("Only raw PCM audio is supported in this implementation.")

        self._push_stream = speechsdk.audio.PushAudioInputStream(stream_format=audio_format_obj)
        self._audio_config = speechsdk.audio.AudioConfig(stream=self._push_stream)
        self._recognizer = speechsdk.SpeechRecognizer(
            speech_config=self._speech_config,
            audio_config=self._audio_config,
        )

    def _normalize_result(self, evt: Any) -> dict:
        result = evt.result
        return {
            "text": getattr(result, "text", ""),
            "reason": str(getattr(result, "reason", "")),
            "offset": getattr(result, "offset", None),
            "duration": getattr(result, "duration", None),
            "session_id": getattr(evt, "session_id", None),
        }

    def recognize_stream(
        self,
        audio_chunks: Iterable[bytes],
        on_partial: Optional[Callable[[dict], None]] = None,
        on_final: Optional[Callable[[dict], None]] = None,
    ) -> Iterator[dict]:
        partial_queue: "queue.Queue[dict]" = queue.Queue()
        final_queue: "queue.Queue[dict]" = queue.Queue()
        done_queue: "queue.Queue[bool]" = queue.Queue()

        def recognized_handler(evt: Any) -> None:
            payload = self._normalize_result(evt)
            if payload["text"]:
                final_queue.put(payload)
                if on_final:
                    on_final(payload)

        def recognizing_handler(evt: Any) -> None:
            payload = self._normalize_result(evt)
            if payload["text"]:
                partial_queue.put(payload)
                if on_partial:
                    on_partial(payload)

        def canceled_handler(evt: Any) -> None:
            payload = {
                "text": "",
                "reason": str(getattr(evt, "reason", "")),
                "error_details": getattr(evt, "error_details", None),
                "session_id": getattr(evt, "session_id", None),
            }
            final_queue.put(payload)
            done_queue.put(True)

        def session_stopped_handler(evt: Any) -> None:
            done_queue.put(True)

        self._recognizer.recognizing.connect(recognizing_handler)
        self._recognizer.recognized.connect(recognized_handler)
        self._recognizer.canceled.connect(canceled_handler)
        self._recognizer.session_stopped.connect(session_stopped_handler)

        self._recognizer.start_continuous_recognition()

        try:
            for chunk in audio_chunks:
                if not chunk:
                    continue
                self._push_stream.write(chunk)

                while True:
                    try:
                        yield {"type": "partial", **partial_queue.get_nowait()}
                    except queue.Empty:
                        break

                while True:
                    try:
                        yield {"type": "final", **final_queue.get_nowait()}
                    except queue.Empty:
                        break

            self._push_stream.close()
            self._recognizer.stop_continuous_recognition()

            while True:
                try:
                    yield {"type": "partial", **partial_queue.get_nowait()}
                except queue.Empty:
                    break

            while True:
                try:
                    yield {"type": "final", **final_queue.get_nowait()}
                except queue.Empty:
                    break

        finally:
            try:
                self._push_stream.close()
            except Exception:
                pass
            try:
                self._recognizer.stop_continuous_recognition()
            except Exception:
                pass

    def transcribe(
        self,
        audio_chunks: Iterable[bytes],
        on_partial: Optional[Callable[[dict], None]] = None,
        on_final: Optional[Callable[[dict], None]] = None,
    ) -> list[dict]:
        return list(self.recognize_stream(audio_chunks, on_partial=on_partial, on_final=on_final))
